"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["51632"],{25354(e,t,n){n.r(t),n.d(t,{metadata:()=>s,default:()=>u,frontMatter:()=>c,contentTitle:()=>d,toc:()=>l,assets:()=>p});var s=JSON.parse('{"id":"nhcx/v1/api/session/endpoints/session-api-hiecm-gateway-v3-sessions","title":"Submit the session token","description":"Mints the ABDM gateway session token that every NHCX call carries, from the client ID and secret you received when you registered on the ABDM sandbox...","source":"@site/docs/nhcx/v1/api/session/endpoints/session-api-hiecm-gateway-v3-sessions.mdx","sourceDirName":"nhcx/v1/api/session/endpoints","slug":"/nhcx/v1/api/session/endpoints/session-api-hiecm-gateway-v3-sessions","permalink":"/docs/pr-48/docs/nhcx/v1/api/session/endpoints/session-api-hiecm-gateway-v3-sessions","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Submit the session token","sidebar_label":"Submit the session token","sidebar_class_name":"api-method api-method--post","description":"Mints the ABDM gateway session token that every NHCX call carries, from the client ID and secret you received when you registered on the ABDM sandbox...","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","source":"nhcx-session.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Overview","permalink":"/docs/pr-48/docs/nhcx/v1/api/session/"},"next":{"title":"Overview","permalink":"/docs/pr-48/docs/nhcx/v1/api/registry/"}}'),i=n(62540),a=n(43023),r=n(52563),o=JSON.parse('{"id":"session_api_hiecm_gateway_v3_sessions","module":"Session","moduleId":"session","kind":"operation","method":"POST","path":"/api/hiecm/gateway/v3/sessions","server":"https://dev.abdm.gov.in","servers":[{"url":"https://dev.abdm.gov.in","description":"Sandbox, ABDM session token."},{"url":"https://apis.abdm.gov.in","description":"Production."}],"summary":"Session token","title":"Submit the session token","description":"Mints the ABDM gateway session token that every NHCX call carries, from the client ID and secret you received when you registered on the ABDM sandbox (`ABDM_CLIENT_ID` and `ABDM_CLIENT_SECRET`).\\n\\n### Business purpose\\n\\nThe token does not come from NHCX. It comes from the ABDM gateway, and one token serves every call: the participant service, the use-case endpoints and the status check. Nothing else in this collection works without it, which is why the post-response script below stores it in `token`, so that running this request once arms the rest of the collection.\\n\\n### When to use\\n\\nCall it before your first NHCX call. Call it again when your token is more than about 18 minutes old, ahead of its 20-minute (1200-second) expiry, or when any call answers `401`.\\n\\n### Preconditions\\n\\n- You hold the client ID and secret you received when you registered on the ABDM sandbox (`ABDM_CLIENT_ID` and `ABDM_CLIENT_SECRET`).\\n- `REQUEST-ID` is a new UUID and `TIMESTAMP` is the current UTC time from a synced clock.\\n- `X-CM-ID` is `sbx` on the sandbox.\\n- The body sets `grantType` to `client_credentials`.\\n\\n### Postconditions\\n\\nThe gateway returns an access token in `accessToken`. Send it on every NHCX call in the `bearer_auth` header, as `Bearer <token>`. The token lasts 1200 seconds (20 minutes), stated in `expiresIn`.\\n\\n### Common mistakes\\n\\n- Copying a `REQUEST-ID` from an example instead of making a new one.\\n- Typing the `TIMESTAMP` by hand, or reading it from a clock that has drifted.\\n- Leaving out `grantType`, as older samples do.\\n- Sending the token without the `Bearer ` prefix.\\n\\n### Best practices\\n\\n- Keep the token together with the time you got it, and fetch a new one before a call if it is more than about 18 minutes old, ahead of the 20-minute expiry.\\n- On any `401`, get a new token and retry that call once.\\n- Send the token in `bearer_auth` on every NHCX call.\\n- Keep the clock synchronised with NTP and let a date library format the timestamp.\\n\\n### Related scenario\\n\\nA hospital\'s integration starts its first eligibility check of the day. It posts this request with a new `REQUEST-ID`, the current UTC `TIMESTAMP` and `X-CM-ID` `sbx`, stores the `accessToken` with the time it arrived, and sends it on the check as `bearer_auth: Bearer <token>`. Later a claim call answers `401 Sender is not authorized to execute the operation`. The integration mints a fresh token, retries the claim once, and it goes through.\\n\\n### Specification\\n\\nChapter [Base URLs](/docs/nhcx/v1/getting-started/base-urls) of the NHCX integration specification.","gateway":"nhcx","security":[],"headers":[{"name":"REQUEST-ID","required":true,"description":"`REQUEST-ID` is a fresh UUID that you generate for every call. Sending the same one twice is the mistake to avoid; generate it, do not copy it from an example.","example":"<uuid>","type":"string"},{"name":"TIMESTAMP","required":true,"description":"`TIMESTAMP` is the current time in UTC, ISO 8601 with milliseconds and a trailing `Z`, as in `2026-09-04T06:15:51.975Z`. A clock that has drifted will be refused, so take the time from the system rather than constructing it by hand. How to produce it in each language is at the end of this chapter.","example":"<iso timestamp>","type":"string"},{"name":"X-CM-ID","required":true,"description":"`X-CM-ID` names the environment. It is `sbx` on the sandbox. The mirror and the adapter both use lowercase.","example":"sbx","type":"string"}],"pathParams":[],"queryParams":[],"body":[{"name":"clientId","type":"string","required":false,"description":"","encrypted":false},{"name":"clientSecret","type":"string","required":false,"description":"","encrypted":false},{"name":"grantType","type":"string","required":false,"description":"","encrypted":false}],"requestExample":{"clientId":"<client id>","clientSecret":"<client secret>","grantType":"client_credentials"},"responses":[{"status":"200","description":"The gateway returns `accessToken`, `expiresIn` `1200` (20 minutes), `refreshToken` and `tokenType` `bearer`.","example":{"accessToken":"eyJhbGciOiJSUzI1NiIs...","expiresIn":1200,"refreshTokenIn":300,"refreshToken":"eyJhbGciOiJSUzI1NiIs...","tokenType":"bearer"},"synthesised":false,"fields":[{"name":"accessToken","type":"string","required":false,"description":""},{"name":"expiresIn","type":"integer","required":false,"description":""},{"name":"refreshTokenIn","type":"integer","required":false,"description":""},{"name":"refreshToken","type":"string","required":false,"description":""},{"name":"tokenType","type":"string","required":false,"description":""}]}],"curl":"curl --request POST \\\\\\n  --url https://dev.abdm.gov.in/api/hiecm/gateway/v3/sessions \\\\\\n  --header \'REQUEST-ID: <uuid>\' \\\\\\n  --header \'TIMESTAMP: <iso timestamp>\' \\\\\\n  --header \'X-CM-ID: sbx\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"clientId\\": \\"<client id>\\",\\n  \\"clientSecret\\": \\"<client secret>\\",\\n  \\"grantType\\": \\"client_credentials\\"\\n}\'","samples":[{"id":"curl","label":"cURL","language":"bash","code":"curl --request POST \\\\\\n  --url https://dev.abdm.gov.in/api/hiecm/gateway/v3/sessions \\\\\\n  --header \'REQUEST-ID: <uuid>\' \\\\\\n  --header \'TIMESTAMP: <iso timestamp>\' \\\\\\n  --header \'X-CM-ID: sbx\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"clientId\\": \\"<client id>\\",\\n  \\"clientSecret\\": \\"<client secret>\\",\\n  \\"grantType\\": \\"client_credentials\\"\\n}\'"},{"id":"python","label":"Python","language":"python","code":"import requests\\n\\nresponse = requests.post(\\n    \\"https://dev.abdm.gov.in/api/hiecm/gateway/v3/sessions\\",\\n    headers={\\n        \\"REQUEST-ID\\": \\"<uuid>\\",\\n        \\"TIMESTAMP\\": \\"<iso timestamp>\\",\\n        \\"X-CM-ID\\": \\"sbx\\",\\n        \\"Content-Type\\": \\"application/json\\",\\n    },\\n    json={\\n        \\"clientId\\": \\"<client id>\\",\\n        \\"clientSecret\\": \\"<client secret>\\",\\n        \\"grantType\\": \\"client_credentials\\"\\n    },\\n)\\n\\nprint(response.status_code, response.text)"},{"id":"node","label":"Node.js","language":"javascript","code":"const response = await fetch(\\"https://dev.abdm.gov.in/api/hiecm/gateway/v3/sessions\\", {\\n  method: \\"POST\\",\\n  headers: {\\n    \\"REQUEST-ID\\": \\"<uuid>\\",\\n    \\"TIMESTAMP\\": \\"<iso timestamp>\\",\\n    \\"X-CM-ID\\": \\"sbx\\",\\n    \\"Content-Type\\": \\"application/json\\",\\n  },\\n  body: JSON.stringify({\\n    \\"clientId\\": \\"<client id>\\",\\n    \\"clientSecret\\": \\"<client secret>\\",\\n    \\"grantType\\": \\"client_credentials\\"\\n  }),\\n});\\n\\nconsole.log(response.status, await response.text());"},{"id":"java","label":"Java","language":"java","code":"import java.net.URI;\\nimport java.net.http.HttpClient;\\nimport java.net.http.HttpRequest;\\nimport java.net.http.HttpResponse;\\n\\nHttpClient client = HttpClient.newHttpClient();\\nHttpRequest request = HttpRequest.newBuilder()\\n    .uri(URI.create(\\"https://dev.abdm.gov.in/api/hiecm/gateway/v3/sessions\\"))\\n    .header(\\"REQUEST-ID\\", \\"<uuid>\\")\\n    .header(\\"TIMESTAMP\\", \\"<iso timestamp>\\")\\n    .header(\\"X-CM-ID\\", \\"sbx\\")\\n    .header(\\"Content-Type\\", \\"application/json\\")\\n    .method(\\"POST\\", HttpRequest.BodyPublishers.ofString(\\"\\"\\"\\n        {\\n            \\"clientId\\": \\"<client id>\\",\\n            \\"clientSecret\\": \\"<client secret>\\",\\n            \\"grantType\\": \\"client_credentials\\"\\n        }\\n        \\"\\"\\"))\\n    .build();\\n\\nHttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());\\nSystem.out.println(response.statusCode() + \\" \\" + response.body());"},{"id":"php","label":"PHP","language":"php","code":"<?php\\n\\n$ch = curl_init(\'https://dev.abdm.gov.in/api/hiecm/gateway/v3/sessions\');\\ncurl_setopt_array($ch, [\\n    CURLOPT_CUSTOMREQUEST => \'POST\',\\n    CURLOPT_RETURNTRANSFER => true,\\n    CURLOPT_HTTPHEADER => [\\n        \'REQUEST-ID: <uuid>\',\\n        \'TIMESTAMP: <iso timestamp>\',\\n        \'X-CM-ID: sbx\',\\n        \'Content-Type: application/json\',\\n    ],\\n    CURLOPT_POSTFIELDS => <<<\'JSON\'\\n    {\\n        \\"clientId\\": \\"<client id>\\",\\n        \\"clientSecret\\": \\"<client secret>\\",\\n        \\"grantType\\": \\"client_credentials\\"\\n    }\\n    JSON,\\n]);\\n\\n$response = curl_exec($ch);\\necho curl_getinfo($ch, CURLINFO_HTTP_CODE), \' \', $response, PHP_EOL;"},{"id":"go","label":"Go","language":"go","code":"package main\\n\\nimport (\\n\\t\\"fmt\\"\\n\\t\\"io\\"\\n\\t\\"net/http\\"\\n\\t\\"strings\\"\\n)\\n\\nfunc main() {\\n\\tbody := strings.NewReader(`{\\n  \\"clientId\\": \\"<client id>\\",\\n  \\"clientSecret\\": \\"<client secret>\\",\\n  \\"grantType\\": \\"client_credentials\\"\\n}`)\\n\\treq, err := http.NewRequest(\\"POST\\", \\"https://dev.abdm.gov.in/api/hiecm/gateway/v3/sessions\\", body)\\n\\tif err != nil {\\n\\t\\tpanic(err)\\n\\t}\\n\\treq.Header.Set(\\"REQUEST-ID\\", \\"<uuid>\\")\\n\\treq.Header.Set(\\"TIMESTAMP\\", \\"<iso timestamp>\\")\\n\\treq.Header.Set(\\"X-CM-ID\\", \\"sbx\\")\\n\\treq.Header.Set(\\"Content-Type\\", \\"application/json\\")\\n\\n\\tresp, err := http.DefaultClient.Do(req)\\n\\tif err != nil {\\n\\t\\tpanic(err)\\n\\t}\\n\\tdefer resp.Body.Close()\\n\\tout, _ := io.ReadAll(resp.Body)\\n\\tfmt.Println(resp.StatusCode, string(out))\\n}"},{"id":"csharp","label":"C#","language":"csharp","code":"using var client = new HttpClient();\\nvar request = new HttpRequestMessage(new HttpMethod(\\"POST\\"), \\"https://dev.abdm.gov.in/api/hiecm/gateway/v3/sessions\\");\\nrequest.Headers.TryAddWithoutValidation(\\"REQUEST-ID\\", \\"<uuid>\\");\\nrequest.Headers.TryAddWithoutValidation(\\"TIMESTAMP\\", \\"<iso timestamp>\\");\\nrequest.Headers.TryAddWithoutValidation(\\"X-CM-ID\\", \\"sbx\\");\\nrequest.Content = new StringContent(\\"\\"\\"\\n    {\\n        \\"clientId\\": \\"<client id>\\",\\n        \\"clientSecret\\": \\"<client secret>\\",\\n        \\"grantType\\": \\"client_credentials\\"\\n    }\\n    \\"\\"\\", System.Text.Encoding.UTF8, \\"application/json\\");\\n\\nvar response = await client.SendAsync(request);\\nConsole.WriteLine($\\"{(int)response.StatusCode} {await response.Content.ReadAsStringAsync()}\\");"},{"id":"ruby","label":"Ruby","language":"ruby","code":"require \'net/http\'\\n\\nuri = URI(\'https://dev.abdm.gov.in/api/hiecm/gateway/v3/sessions\')\\nrequest = Net::HTTP::Post.new(uri)\\nrequest[\'REQUEST-ID\'] = \'<uuid>\'\\nrequest[\'TIMESTAMP\'] = \'<iso timestamp>\'\\nrequest[\'X-CM-ID\'] = \'sbx\'\\nrequest[\'Content-Type\'] = \'application/json\'\\nrequest.body = <<~\'JSON\'\\n  {\\n    \\"clientId\\": \\"<client id>\\",\\n    \\"clientSecret\\": \\"<client secret>\\",\\n    \\"grantType\\": \\"client_credentials\\"\\n  }\\nJSON\\n\\nresponse = Net::HTTP.start(uri.hostname, uri.port, use_ssl: uri.scheme == \'https\') do |http|\\n  http.request(request)\\nend\\nputs response.code, response.body"}]}');let c={title:"Submit the session token",sidebar_label:"Submit the session token",sidebar_class_name:"api-method api-method--post",description:"Mints the ABDM gateway session token that every NHCX call carries, from the client ID and secret you received when you registered on the ABDM sandbox...",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",source:"nhcx-session.yaml",generated:!0},d,p={},l=[];function h(e){return(0,i.jsx)(r.Ay,{operation:o})}function u(e={}){let{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(h,{...e})}):h(e)}}}]);